+const atomicName = '__keaAtomicSelectorName'
+
+/**
+ * A deliberately small selector runtime.  It records reads while computing, then
+ * validates those reads before asking the input selectors to do any work again.
+ * This is important: validating an input selector's object identity would turn a
+ * change to `user.age` into a change to `user.name`.
+ */
+export class AtomicSelectorRuntime {
+  entries: Record<string, Entry> = {}
+  constructor(private logic: BuiltLogic) {
+    logic.selectorHealth = () => this.health()
+  }
+
+  add(name: string, inputs: Selector[], compute: (...args: any[]) => any): Selector {
+    const entry: Entry = {
+      name, inputs, compute, value: undefined, hasValue: false, dependencies: new Set(), selectorDependencies: new Set(),
+      evaluations: 0, dirtyCause: null,
+    }
+    this.entries[name] = entry
+    const selector: any = (state: any, props: any) => this.evaluate(entry, state, props)
+    selector[atomicName] = name
+    return selector
+  }
+
+  private evaluate(entry: Entry, state: any, props: any): any {
+    const changed = entry.hasValue ? this.changedDependency(entry, state) : 'initial'
+    if (entry.hasValue && !changed) return entry.value
