+    const reads = new Set<string>()
+    const selectorReads = new Set<string>()
+    const args = entry.inputs.map((input: any) => {
+      const other = input && input[atomicName]
+      if (other) selectorReads.add(other)
+      return input(this.proxy(state, [], reads), props)
+    })
+    const result = entry.compute(...args)
+    entry.dependencies = pruneParents(reads)
+    entry.selectorDependencies = selectorReads
+    entry.value = unwrap(result)
+    entry.hasValue = true
+    entry.evaluations += 1
+    entry.dirtyCause = changed === 'initial' ? null : changed
+    return entry.value
+  }
+
+  private changedDependency(entry: Entry, state: any): string | null {
+    for (const path of entry.dependencies) {
+      if (readPath(state, this.logic.pathString, path) !== readPath((entry as any)._state, this.logic.pathString, path)) return path
